func worker(id int, jobs <-chan int, results chan<- int, wg *sync.WaitGroup) {
	defer wg.Done()
	for n := range jobs { // ends when jobs is closed & drained
		results <- n * n  // do the work, push the result
	}
}

func main() {
	jobs := make(chan int)
	results := make(chan int)

	var wg sync.WaitGroup
	for id := 1; id <= 3; id++ { // launch a fixed pool of 3
		wg.Add(1)
		go worker(id, jobs, results, &wg)
	}

	go func() { // producer: send all jobs, then close
		for n := 1; n <= 5; n++ {
			jobs <- n
		}
		close(jobs)
	}()

	go func() { wg.Wait(); close(results) }() // close results when all workers done

	sum := 0
	for r := range results { // drain until results is closed
		sum += r
	}
	fmt.Println(sum) // 1+4+9+16+25 = 55
}

